from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,re,subprocess
P=Path(__file__).resolve().parent;S=P.parents[1];R=S.parents[4]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def bind(p):return dict(path=p.relative_to(R).as_posix(),sha256=sha(p))
def write(name,v):
 p=P/name;assert not p.exists();p.write_bytes((json.dumps(v,indent=2)+'\n').encode());return p
assert sha(S/'unblock-nine-20260908/selected-interpretations.json')=='cfde240a9dda9a58be99f85369b43e99003b0024c7147a33ffa8b071ca7dcf34'
paths=[R/'lean-toolchain',R/'lake-manifest.json',P/'REVIEW.md',P/'capture-review.py',S/'unblock-nine-20260908/selected-interpretations.json',S/'current-thread-question-provenance-v2-batch10/projection.json',S/'prospective-source-choice-boundaries-batch10-v2.json']
owners=['Source/LeVeque/Chapter01/AcousticsModes.lean','Source/LeVeque/Chapter01/AcousticsRightModeAlgebraic.lean','Source/LeVeque/Chapter01/EigenvaluePropagation.lean','Source/LeVeque/Chapter01/RiemannHyperbolicProblem.lean','Source/LeVeque/Chapter01/RiemannInitialConfiguration.lean','Analysis/PartialDifferentialEquations/LinearAcoustics.lean','Analysis/PartialDifferentialEquations/LinearAdvection.lean','Analysis/PartialDifferentialEquations/Transport/Characteristics.lean','Analysis/PartialDifferentialEquations/Transport/ClassicalCharacteristics.lean','Analysis/PartialDifferentialEquations/ConservationLaws/TravelingWaveCharacterization.lean','Analysis/PartialDifferentialEquations/LinearSystems/EigenbasisCoordinates.lean','Analysis/PartialDifferentialEquations/LinearSystems/CharacteristicPropagation.lean','Analysis/PartialDifferentialEquations/FirstOrderEquation.lean','Analysis/PartialDifferentialEquations/InitialValue/FirstOrderRiemann.lean','Analysis/PartialDifferentialEquations/FiniteVolume/RiemannData.lean','Analysis/PartialDifferentialEquations/Hyperbolicity.lean']
