paths += [S/n for n in frozen]
ids=['LEV-CH01-ACOUSTICS-LEFT-MODE-CANONICAL-20260908','LEV-CH01-EIGENVALUES-WAVE-SPEEDS-CANONICAL-20260908','LEV-CH01-EIGENVALUES-GENERAL-PROPAGATION-PRODUCTION-20260908','LEV-CH01-RIEMANN-INITIAL-VALUE-DEFINITION-PRODUCTION-20260908','LEV-CH01-RIEMANN-HYPERBOLIC-PROBLEM-DATA-PRODUCTION-20260908']
audits=[]
for task_id in ids:
 d=S/'audits'/task_id;t=json.loads((d/'audit-task.json').read_bytes());v=json.loads((d/'faithfulness/decision.json').read_bytes())
 for n in ['audit-task.json','faithfulness/decision.json','faithfulness/report.md','faithfulness/manifest.json','faithfulness/inputs/source_locator.json']:paths.append(d/n)
 source=R/t['source']['path'];assert sha(source)==t['source']['sha256'];paths.append(source)
 audits.append(dict(task_id=task_id,task=bind(d/'audit-task.json'),target=t['target'],source=t['source'],decision=bind(d/'faithfulness/decision.json'),historical_classification=v['classification'],accepted=v['accepted'],findings=v['findings'],remaining_uncertainties=v['remaining_uncertainties']))
for task,n in [(ids[0],'023'),(ids[0],'024'),(ids[1],'025'),(ids[4],'027')]:paths.append(S/'audits'/task/'faithfulness/orchestration'/('page-'+n+'.png'))
cmd=['rg','-n',r'linearAcousticsLeftInvariant_isLinearAdvectionSolutionAt|travelingWave_isLinearAdvectionSolution_iff|travelingWave_isRectangleConservationLawSolution_iff|constantCoefficientSystem_characteristicPropagation|constantCoefficientSystem_iff_eigenbasisAdvection|isRiemann_characterization|fromEqualStates_not_isJumpRiemann|fromStates_isJumpRiemann|fromStates_isRiemannWithStates','ComputationalMathematics/Analysis/PartialDifferentialEquations','.lake/packages/mathlib/Mathlib','-g','*.lean']
